        payload = _filter_bytes(doc)
    except InvalidInput:
        _fail("invalid_input")
        return 4
    # 输出上界（含末尾 LF）在写出前判定；等于上限合法，失败 stdout 为空
    if len(payload) > max_output_bytes:
        _fail("output_limit")
        return 5
    sys.stdout.buffer.write(payload)
    return 0


